      if (e.pos[0] < x || e.pos[0] > x + 1 || e.pos[2] < z || e.pos[2] > z + 1 || e.pos[1] < y + 0.6 || e.pos[1] > y + 2) continue;
      const left = RS.insert(self, e.stack, 'up');
