    this.mouth = Math.random() < 0.2 ? makeStack(pickW([['emerald', 5], ['rabbit_foot', 10], ['rabbit_hide', 10], ['egg', 15], ['wheat', 20], ['leather', 20], ['feather', 20]]), 1) : null;
