    if (P.left_wing) { P.left_wing.yRot = 0.785 - f * 0.4; P.left_wing.xRot = 0.43; P.left_wing.zRot = 0.47; }
    if (P.head) { P.head.yRot = -(this.headYaw || 0); P.head.xRot = -(this.pitch || 0); }
