      shootAt(this, t, 1.6, { layer: ITEMS[ITEM_KEY.snowball].tex, grav: 0.03, arc: 0.2, yk: 0.85, onHit: (e) => { e.hurt(e.type === 'blaze' ? 3 : 0.0001, { type: 'mob', attacker: this, knockFrom: this.pos, knock: 0.4 }); } });
