    const H = md.parts.head; if (!H) return;
    const mm = M4.copy(m); M4.scale(mm, -1, -1, 1); M4.translate(mm, 0, -1.501, 0);
    M4.translate(mm, H.x / 16, H.y / 16, H.z / 16); M4.rotY(mm, H.yRot); M4.rotX(mm, H.xRot);
