      if (this.baby) { this.growT -= Math.floor(this.growT * 0.1); swapHeld(this.game, p, 'water_bucket'); return true; }
      if (this.breedCd <= 0 && !this.loveT) { this.loveT = 600; swapHeld(this.game, p, 'water_bucket'); this.sound('eat'); return true; }
