  defBlock(3003, 'stripped_poplar_wood', '去皮杨木', { tex: 'stripped_poplar_log', hardness: 2, tool: 'axe', sound: 'wood', axis: true, texFn: logTex, fuel: 300, flammable: true });
  wood(3004, 'poplar_planks', '杨木木板', 'poplar_planks');
