      const [x, y, z] = be.pos;
      if (Math.abs(x - p.pos[0]) > 48 || Math.abs(z - p.pos[2]) > 48 || !isCamp(w.getBlock(x, y, z))) continue;
      const l = w.getLight(x, y + 1, z), L = [(l >> 4) / 15, Math.max(l & 15, 13) / 15];
