        const s = be.items[i]; if (!s) continue;
        const m = M4.create(); M4.translate(m, x + 0.5, y + 0.45, z + 0.5); M4.rotY(m, -i * Math.PI / 2);
        M4.translate(m, -0.3125, 0, -0.3125); M4.rotX(m, -Math.PI / 2); M4.scale(m, 0.75, 0.75, 0.75);
