    if (!n) cmdFail(op === 'add' ? '无法添加标签：目标已有此标签' : '无法移除标签：目标没有此标签');
    ctx.say(`已${op === 'add' ? '为' : '从'} ${ts.length === 1 ? cmdName(this, ts[0]) : n + ' 个实体'} ${op === 'add' ? '添加' : '移除'}标签 ${name}`);
