    if (act === 'list') { const names = a[2] ? ts : Object.keys(S.players); ctx.say(names.length ? '玩家：' + names.map((n) => n + '（' + Object.keys(S.players[n] || {}).map((o) => o + '=' + scoreOf(g, n, o)).join('，') + '）').join('；') : '没有计分玩家', '#FFFFFF', true); return; }
