      for (const n of ts) { const t = scoreOf(g, n, o), s = scoreOf(g, src, so); setScore(g, n, o, op === '=' ? s : op === '+=' ? t + s : op === '-=' ? t - s : op === '*=' ? t * s : op === '/=' ? (s ? t / s : 0) : op === '%=' ? (s ? t % s : 0) : op === '<' ? Math.min(t, s) : op === '>' ? Math.max(t, s) : op === '><' ? s : t); }
