  if (act === 'add') { if (!n) cmdFail('用法：/team add <队伍> [显示名]'); if (S[n]) cmdFail('队伍已存在'); S[n] = { name: n, displayName: a.slice(2).join(' ') || n, color: 'white', prefix: '', suffix: '', players: [] }; ctx.say('已创建队伍 ' + n); return; }
