    if (id === undefined) { this.unknownItems.add(o.n); s.id = ITEM_KEY.stone; s.unk = o.n; }
    if (o.x) s.x = o.x;
    if (o.name) s.name = o.name;
    if (o.lore) s.lore = o.lore;
    if (o.e) s.e = o.e;
