    if (!Account.token || !body) return api(path, body); // (what is only looked at needs no token)
    let r;
    try { r = await fetch(this.base() + path, { method: 'POST', body: JSON.stringify({ ...body, _t: Account.token }) }); }
    catch (e) { throw new Error('连不上联机服务器'); }
