  // is the first one again - the user liked it best)
  attack: ['...........###', '..........####', '.........####.', '........####..', '.......####...', '......####....', '.##..####.....', '.###.###......', '..#####.......', '...###........', '..#####.......', '.###..##......', '###...........', '##............'],
  use: ['..#.#.#..', '..#.#.#..', '..#.#.#.#', '..#######', '.########', '.########', '..#######', '...#####.', '....###..'],
