        if (this.iconImg.complete && this.iconImg.naturalWidth) { ui.ctx.imageSmoothingEnabled = true; ui.ctx.drawImage(this.iconImg, ui.w / 2 - 132, 96, 24, 24); ui.ctx.imageSmoothingEnabled = false; }
