    if (!g.p2pGuest) return;
    this.widgets.push({ x: u.w / 2 + 4, y: u.h / 2 + 67, w: 98, h: 20, label: '房间…', tip: ['联机房间：邀请码、房主、离开'],
      onClick: () => g.ui.open(new LocalGuestRoomScreen(g, this)) });
